begin;
select plan(18);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.subscribe_competitor('00000000-0000-4000-8000-000000000101','shared.example','Original shared fixture','Tenant one private prohibition')$$,'owner subscribes fictional shared source');
select throws_ok($$select public.subscribe_competitor('00000000-0000-4000-8000-000000000101','real.com','Unavailable real source')$$,'23514',null,'real opt-in/capture unavailable');
select throws_ok($$select public.enqueue_reference_job('00000000-0000-4000-8000-000000000101','playbook.synthesize')$$,'23514',null,'incomplete evidence blocks influential playbook');
select public.enqueue_reference_job('00000000-0000-4000-8000-000000000101','competitors.capture',(select id from public.competitor_subscriptions));
select public.claim_job('00000000-0000-4000-8000-000000000101');
select lives_ok($$select public.finish_capture_job((select id from public.job_runs where kind='competitors.capture'),(select lease_token from public.job_runs where kind='competitors.capture'),jsonb_build_object('synthetic',true,'records',(select jsonb_agg(jsonb_build_object('externalId','fixture-v1-'||n,'receivedAt',now()-make_interval(days=>n),'subject','Original synthetic source '||n,'text','<script>hostileFixture()</script> Original escaped text','safeHtml','<img src="https://tracking.invalid"><script>hostile()</script>','micro',jsonb_build_object('offerCode',null,'product',null,'theme','Education','strips',jsonb_build_array('Hero','CTA'),'discountPercent',0,'sequenceHint',null,'synthetic',true))) from generate_series(0,9) n),'sequences','[]'::jsonb))$$,'fixture capture persisted through lease');
select is((select count(*) from public.competitor_emails),10::bigint,'ten original fixture records');
select ok((select bool_and(safe_html not like '%<script>%' and safe_html not like '%<img%') from public.competitor_emails),'hostile caller HTML and unescaped text excluded');
select is(public.enqueue_reference_job('00000000-0000-4000-8000-000000000101','competitors.capture',(select id from public.competitor_subscriptions)),(select id from public.job_runs where kind='competitors.capture'),'capture replay idempotent');
select is((select status from public.competitor_captures),'live','fixture opt-in/status transitions to LIVE');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select is((select count(*) from public.competitor_emails),0::bigint,'unsubscribed tenant cannot see capture');
select lives_ok($$select public.subscribe_competitor('00000000-0000-4000-8000-000000000102','shared.example','Other fixture label','Tenant two different private rule')$$,'second tenant reuses capture identity');
select is((select count(*) from public.competitor_captures),1::bigint,'one shared identity');
select is((select count(*) from public.competitor_emails),10::bigint,'subscribed tenant sees shared safe records');
select is((select private_rules from public.competitor_subscriptions),'Tenant two different private rule','other private rules excluded');
select throws_ok($$select public.update_competitor_subscription('00000000-0000-4000-8000-000000000102',(select id from public.competitor_subscriptions),99,false,'')$$,'40001',null,'stale subscription update rejected');
select lives_ok($$select public.update_competitor_subscription('00000000-0000-4000-8000-000000000102',(select id from public.competitor_subscriptions),1,false,'')$$,'unsubscribe persists');
select is((select count(*) from public.competitor_emails),0::bigint,'unsubscribe revokes capture reads');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*) from public.competitor_emails),0::bigint,'designer cannot enumerate reference email content');
select is((select count(*) from public.playbooks),0::bigint,'designer cannot see tenant-private playbooks');
select * from finish();rollback;
